package dev.pocketengine.features.memory;

import dev.pocketengine.core.ModelConfig;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.runtime.usage.InferenceCapture;
import dev.pocketengine.runtime.usage.InferenceReceipt;
import java.util.ArrayList;
import java.util.List;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

/** Pure JSON/identity and real InferenceCapture dispatch order. No network/provider fixture. */
public final class SourceLearningJobContractTest {
    private static JSONObject input()throws Exception{return new JSONObject().put("sourceRef",new SourceRef("message","exact-source",9_000_000_000L,"owner","private").toJson()).put("sourceFingerprint","sha256:"+"a".repeat(64)).put("title","主人原话");}
    private static ModelConfig model(){return new ModelConfig("https://fixture.invalid","private-test-key","fixture-model",false,20,10);}
    @Test public void manifestsRemainBodyFreeExactLongVersionsAndDefensiveCopies()throws Exception{JSONObject source=input();JSONArray checked=SourceLearningJob.checkedInputs(new JSONArray().put(source));assertEquals(9_000_000_000L,checked.getJSONObject(0).getJSONObject("sourceRef").getLong("revision"));source.put("title","UI后来变化");assertEquals("主人原话",checked.getJSONObject(0).getString("title"));assertEquals(3,checked.getJSONObject(0).length());assertFalse(checked.toString().contains("executionAuthorized"));}
    @Test public void duplicateBodyForeignScopeAndHashAsRevisionAreRejected()throws Exception{assertThrows(Exception.class,()->SourceLearningJob.checkedInputs(new JSONArray()));assertThrows(Exception.class,()->SourceLearningJob.checkedInputs(new JSONArray().put(input()).put(input())));assertThrows(Exception.class,()->SourceLearningJob.checkedInputs(new JSONArray().put(input().put("text","替代正文"))));JSONObject foreign=input();foreign.getJSONObject("sourceRef").put("spaceId","group:elsewhere");assertThrows(Exception.class,()->SourceLearningJob.checkedInputs(new JSONArray().put(foreign)));JSONObject hash=input();hash.getJSONObject("sourceRef").put("revision","sha256:"+"a".repeat(64));assertThrows(Exception.class,()->SourceLearningJob.checkedInputs(new JSONArray().put(hash)));}
    @Test public void draftValidationCannotTurnModelPayloadIntoScopeGrantOrVerifiedSkill()throws Exception{JSONObject draft=new JSONObject().put("layer","procedural").put("text","方法").put("reason","有限来源").put("applicability","特定前提，不满足时停").put("confidence",0.5);assertEquals("procedural",MemoryBook.checkedLearningDraft(draft).getString("layer"));assertThrows(Exception.class,()->MemoryBook.checkedLearningDraft(new JSONObject(draft.toString()).put("scope",new JSONObject().put("spaceId","private"))));assertThrows(Exception.class,()->MemoryBook.checkedLearningDraft(new JSONObject(draft.toString()).put("allowed-tools",new JSONArray().put("shell"))));assertThrows(Exception.class,()->MemoryBook.checkedLearningDraft(new JSONObject(draft.toString()).put("applicability","")));}
    @Test public void admissionCompositionPreservesOriginalThenExtraBeforeAndAfterDurableStart()throws Exception{List<String> order=new ArrayList<>();var context=InferenceReceipt.Context.unattributed();var target=new InferenceCapture.Target(context,new InferenceCapture.Sink(){public void started(InferenceReceipt r){order.add("durable-start");}public void finished(InferenceReceipt r){order.add("durable-finish:"+r.outcome.name());}},()->order.add("original"));var observed=InferenceCapture.observe(InferenceCapture.withAdmission(target,()->order.add("source-current")),new InferenceCapture.Sink(){public void started(InferenceReceipt r){order.add("observer-start");}public void finished(InferenceReceipt r){order.add("observer-finish");}});assertSame(context,observed.context);var capture=new InferenceCapture(model(),new RunControl(),observed);capture.dispatch();capture.finish(InferenceReceipt.Outcome.COMPLETED);assertEquals(List.of("original","source-current","durable-start","observer-start","original","source-current","durable-finish:COMPLETED","observer-finish"),order);}
    @Test public void sourceFailureAfterStartLeavesRealUnknownRatherThanRefundOrSecondDispatch()throws Exception{int[] admissions={0},starts={0},ends={0};var target=InferenceCapture.withAdmission(new InferenceCapture.Target(InferenceReceipt.Context.unattributed(),new InferenceCapture.Sink(){public void started(InferenceReceipt r){starts[0]++;assertEquals(InferenceReceipt.Outcome.STARTED,r.outcome);}public void finished(InferenceReceipt r){ends[0]++;}}),()->{if(++admissions[0]==2)throw new SecurityException("forgotten");});var capture=new InferenceCapture(model(),new RunControl(),target);assertThrows(Exception.class,capture::dispatch);assertEquals(1,starts[0]);assertEquals(0,ends[0]);assertThrows(NullPointerException.class,()->InferenceCapture.withAdmission(null,()->{}));assertThrows(NullPointerException.class,()->InferenceCapture.withAdmission(target,null));}
    private static SourceLearningJob.OwnerCommands commands(int[] called){return new SourceLearningJob.OwnerCommands(){private JSONObject result(){called[0]++;return new JSONObject();}public JSONObject create(JSONArray r){return result();}public JSONObject add(String t,long r,SourceRef s){return result();}public JSONObject get(String t){return result();}public JSONObject list(String c,int l){return result();}public JSONObject run(String t,long r,RunControl c){return result();}public JSONObject skip(String t,long r,boolean c){return result();}public JSONObject stop(String t,String r,int e){return result();}};}
    @Test public void nativeOwnerDispatcherRequiresTrueConsentAndCannotAcceptModelOrGrantOverrides()throws Exception{int[] called={0};var host=commands(called);JSONObject run=new JSONObject().put("taskId","native-original").put("revision",1L).put("confirmModelUse",true);SourceLearningJob.dispatch("runLearningJob",run,new RunControl(),host);assertEquals(1,called[0]);for(Object bad:new Object[]{"true",false,1,JSONObject.NULL})assertThrows(Exception.class,()->SourceLearningJob.dispatch("runLearningJob",new JSONObject(run.toString()).put("confirmModelUse",bad),new RunControl(),host));assertThrows(Exception.class,()->SourceLearningJob.dispatch("runLearningJob",new JSONObject(run.toString()).put("model","free-provider"),new RunControl(),host));assertThrows(Exception.class,()->SourceLearningJob.dispatch("runLearningJob",new JSONObject(run.toString()).put("revision",1.0),new RunControl(),host));assertThrows(Exception.class,()->SourceLearningJob.dispatch("tool_native_memory_learning_batch",run,new RunControl(),host));assertEquals(1,called[0]);}
    @Test public void cancelledNativeOwnerCommandCannotCreateOrSkipAPlan()throws Exception{int[] called={0};RunControl cancelled=new RunControl();cancelled.cancel();assertThrows(Exception.class,()->SourceLearningJob.dispatch("createLearningJob",new JSONObject().put("sourceRefs",new JSONArray().put(input().getJSONObject("sourceRef"))),cancelled,commands(called)));assertThrows(Exception.class,()->SourceLearningJob.dispatch("skipLearningJobBatch",new JSONObject().put("taskId","native-original").put("revision",1).put("confirmUnknownUse","true"),new RunControl(),commands(called)));assertEquals(0,called[0]);}
    @Test public void stopCannotBorrowCurrentRunFromTaskIdOrCoerceAnEpoch()throws Exception{
        int[] called={0};var host=commands(called);JSONObject exact=new JSONObject().put("taskId","native-original").put("runId","original-run").put("epoch",2);
        assertThrows(SecurityException.class,()->SourceLearningJob.dispatch("stopLearningJob",new JSONObject().put("taskId","native-original"),new RunControl(),host));
        for(Object bad:new Object[]{"2",2.0,-1,0,4_294_967_298L})assertThrows(SecurityException.class,()->SourceLearningJob.dispatch("stopLearningJob",new JSONObject(exact.toString()).put("epoch",bad),new RunControl(),host));
        SourceLearningJob.dispatch("stopLearningJob",exact,new RunControl(),host);assertEquals(1,called[0]);
    }

    @Test public void executionContractCannotCarryAuthorityOrWrapFutureLongVersionsIntoCurrentSchema()throws Exception{
        JSONObject current=LearningExtractionContract.capture(LearningExtractionContract.SOURCE,null);assertTrue(LearningExtractionContract.supported(current));
        assertThrows(SecurityException.class,()->LearningExtractionContract.checked(new JSONObject(current.toString()).put("executionAuthorized",true)));
        assertThrows(SecurityException.class,()->LearningExtractionContract.checked(new JSONObject(current.toString()).put("sourceCharsLimit",24000.0)));
        assertFalse(LearningExtractionContract.supported(new JSONObject(current.toString()).put("assertionVersion",4_294_967_296L+MemoryAssertion.VERSION)));
        assertFalse(LearningExtractionContract.supported(new JSONObject(current.toString()).put("sourceCharsLimit",4_294_967_296L+LearningExtractionContract.SOURCE_CHARS)));
        assertThrows(SecurityException.class,()->LearningExtractionContract.capture(LearningExtractionContract.OWNER_QUOTE,null));
        assertEquals("contract_unverifiable_requires_review",LearningExtractionContract.publicationStatus(new JSONObject().put("format","pocketworld.source-learning-draft.future")));
    }

    @Test public void taskEpisodeContractKeepsNativeOutcomeAndSeparateOwnerReview()throws Exception{
        JSONObject contract=LearningExtractionContract.capture(LearningExtractionContract.EPISODE,null);assertTrue(LearningExtractionContract.supported(contract));assertEquals("ended_task_episode",contract.getString("mode"));assertTrue(contract.isNull("ownerPolicyFingerprint"));assertEquals("pending_native_owner_review",contract.getString("publication"));
        String instruction=LearningExtractionContract.instruction(LearningExtractionContract.EPISODE);assertTrue(instruction.contains("unknown"));assertTrue(instruction.contains("episodic"));assertTrue(instruction.contains("operationId"));assertNotEquals(LearningExtractionContract.capture(LearningExtractionContract.SOURCE,null).getString("promptSha256"),contract.getString("promptSha256"));assertThrows(SecurityException.class,()->LearningExtractionContract.capture(LearningExtractionContract.EPISODE,new JSONObject()));
    }

}
